ng:.1em;margin-top:3px}.round-label b{color:#ffe27b}.screen-overlay{position:absolute;inset:0;z-index:4;display:grid;place-items:center;background:linear-gradient(90deg,#18242b70,#18242b29 60%,#18242b60);transition:opacity .25s}.screen-overlay.playing{pointer-events:none;opacity:0}.intro-card,.end-card{width:min(360px,78%);padding:25px 31px 18px;background:#f4f1e8;border:3px solid #17232a;box-shadow:7px 7px 0 #17232a;transform:rotate(-1deg);text-align:left}.card-kicker{font:500 8px 'DM Mono',monospace;letter-spacing:.12em;color:#6b7778;margin-bottom:12px}.card-kicker span{color:var(--orange)}.intro-card h2,.end-card h2{font-size:44px;line-height:.8;letter-spacing:-.08em;margin:0 0 13px}.intro-card h2 em,.end-card h2 em{font-style:normal;color:var(--orange)}.intro-card p,.end-card p{font-size:12px;line-height:1.55;color:#5d6a6d;margin:0 0 17px;max-width:270px}.play-button{display:flex;justify-content:space-between;align-items:center;width:100%;border:0;background:var(--orange);color:#fff;padding:12px 14px;font:700 11px 'Space Grotesk',sans-serif;letter-spacing:.1em;cursor:pointer;box-shadow:0 3px #b84926;transition:transform .1s,box-shadow .1s}.play-button:hover{transform:translateY(-2px);box-shadow:0 5px #b84926}.play-button:active{transform:translateY(2px);box-shadow:0 1px #b84926}.play-button b{font-size:18px}.card-foot{display:flex;justify-content:space-between;margin-top:15px;font:8px 'DM Mono',monospace;letter-spacing:.07em;color:#92958b}.hidden{display:none!important}.pause-badge{background:#f4f1e8;border:3px solid #17232a;padding:15px 25px;box-shadow:5px 5px #17232a;font-weight:700;letter-spacing:.12em;transform:rotate(-2deg)}.pause-badge span{color:var(--orange);margin-left:8px}.toast{position:absolute;z-index:5;left:50%;top:23%;transform:translate(-50%,-10px);background:#f4f1e8;border:2px solid #17232a;padding:8px 13px;font:500 11px 'DM Mono',monospace;letter-spacing:.08em;opacity:0;transition:.25s;pointer-events:none;white-space:nowrap;box-shadow:3px 3px #