8px 'DM Mono',monospace;letter-spacing:.06em;color:#6f7a7c}.key-group{display:flex;gap:3px}.key-group kbd{font:500 9px 'DM Mono',monospace;min-width:20px;height:21px;padding:4px 5px;text-align:center;background:#eae8df;border:1px solid #d2d0c6;border-bottom-width:2px;color:#243138}.key-group kbd.wide{min-width:52px}.tip-box{display:flex;gap:10px;background:#eae9d9;padding:11px;margin-top:14px}.tip-box>span{font-size:16px;color:#91a64a}.tip-box p{font-size:9px;line-height:1.5;color:#687276;margin:0}.tip-box b{font:500 8px 'DM Mono',monospace;letter-spacing:.08em;color:#3d4b4d}.side-footer{display:flex;justify-content:space-between;margin-top:auto;padding:3px 1px 0;font:7px 'DM Mono',monospace;letter-spacing:.04em;color:#989b91}.page-footer{display:flex;justify-content:space-between;border-top:1px solid #c9c7bd;margin-top:25px;padding-top:13px;font:8px 'DM Mono',monospace;letter-spacing:.1em;color:#89908a}.page-footer b{color:var(--orange);font-size:12px}.touch-controls{display:none}
