z-index:10;left:0;right:0;bottom:0;padding:10px 18px max(13px,env(safe-area-inset-bottom));display:flex;justify-content:space-between;align-items:flex-end;pointer-events:none;background:linear-gradient(0deg,#e8e5dcf2 70%,#e8e5dc00)}.dpad{width:118px;height:96px;display:grid;grid-template-columns:repeat(3,36px);grid-template-rows:repeat(3,30px);gap:3px;pointer-events:auto}.dpad button,.touch-actions button{border:1px solid #aeb1a6;background:#f4f1e8;color:#26353a;font:700 12px 'DM Mono',monospace;box-shadow:0 3px #c7c6bb;touch-action:none}.dpad button:nth-child(1){grid-column:2;grid-row:1}.dpad button:nth-child(2){grid-column:1;grid-row:2}.dpad button:nth-child(3){grid-column:2;grid-row:2}.dpad button:nth-child(4){grid-column:3;grid-row:2}.touch-actions{display:flex;align-items:flex-end;gap:9px;pointer-events:auto}.touch-actions button{border-radius:50%;width:65px;height:65px;font-size:9px;letter-spacing:.04em}.touch-actions .touch-punch{width:76px;height:76px;background:var(--orange);border-color:#b84926;color:white;box-shadow:0 4px #a74222}.touch-actions button:active,.dpad button:active{transform:translateY(2px);box-shadow:none}}
@media(max-width:390px){.game-shell{padding-left:10px;padding-right:10px}.side-panel{grid-template-columns:1fr}.controls-card{grid-column:auto}.side-footer{grid-column:auto}.mission-card h2{font-size:22px}.controls-card{display:none}.game-caption{font-size:6px}.touch-controls{padding-left:10px;padding-right:10px}.touch-actions button{width:58px;height:58px}.touch-actions .touch-punch{width:70px;height:70px}}
