(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;
  const $ = id => document.getElementById(id);
  const overlay = $('overlay'), intro = $('introCard'), endCard = $('endCard'), pauseBadge = $('pauseBadge');
  const keys = new Set();
  const state = {mode:'intro', score:0, time:90, defeats:0, total:8, last:0, spawnWait:0, toastTimer:0, shake:0, sound:true, anim:0};
  const player = {x:480,y:423,vx:0,vy:0,face:1,hp:100,maxHp:100,speed:210,attack:0,dash:0,dashLock:0,invuln:0,anim:0};
  let enemies=[], snacks=[], particles=[], audioCtx=null;
  const rand=(a,b)=>a+Math.random()*(b-a), clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  const rounded=(c,x,y,w,h,r)=>{c.beginPath();c.roundRect(x,y,w,h,r);};
  function sound(freq=440,duration=.08,type='square',volume=.045){ if(!state.sound)return; try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)(); const o=audioCtx.createOscillator(),g=audioCtx.createGain(); o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration)}catch(e){} }
  function showToast(message){ const t=$('toast');t.textContent=message;t.classList.add('show');state.toastTimer=1.35; }
  function updateHud(){ $('healthFill').style.width=`${player.hp}%`; $('score').textContent=String(state.score).padStart(6,'0'); const s=Math.max(0,Math.ceil(state.time)); $('timer').textContent=`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`; $('missionCount').textContent=`${state.defeats} / ${state.total}`; $('missionProgress').style.width=`${state.defeats/state.total*100}%`; $('waveText').textContent=state.defeats>=state.total?'COURTYARD CLEARED':state.mode==='playing'?'BULLIES LEFT: '+(state.total-state.defeats):'READY WHEN YOU ARE'; }
  function startGame(){ state.mode='playing';state.score=0;state.time=90;state.defeats=0;state.spawnWait=0;player.x=480;player.y=423;player.hp=100;player.face=1;player.attack=0;player.dash=0;player.dashLock=0;player.invuln=0;enemies=[];snacks=[];particles=[];overlay.classList.add('playing');intro.classList.remove('hidden');endCard.classList.add('hidden');pauseBadge.classList.add('hidden');$('round').textContent='01'; spawnEnemy();spawnEnemy();updateHud();sound(580,.11,'triangle'); }
  function finishGame(won){state.mode=won?'won':'lost';overlay.classList.remove('playing');pauseBadge.classList.add('hidden');intro.classList.add('hidden');endCard.classList.remove('hidden');$('endKicker').textContent=won?'NEIGHBORHOOD REPORT':'BACK TO THE BARREL';$('endTitle').innerHTML=won?'NICE<br><em>WORK!</em>':'OH, <em>NO!</em><br>TRY AGAIN';$('endText').textContent=won?`You sent the bullies packing and scored ${String(state.score).padStart(6,'0')} points. The courtyard is yours!`:'The bullies took over this round. Catch your breath and give it another go.';$('restartButton').focus();sound(won?760:180,.28,'sawtooth');updateHud(); }
  function pauseGame(){if(state.mode==='playing'){state.mode='paused';pauseBadge.classList.remove('hidden');overlay.classList.remove('playing')}else if(state.mode==='paused'){state.mode='playing';pauseBadge.classList.add('hidden');overlay.classList.add('playing');state.last=performance.now()}}
  function spawnEnemy(){if(state.defeats+enemies.length>=state.total)return; let x=rand(110,850),y=rand(326,365); if(Math.abs(x-player.x)<110)x=x<480?120:840; enemies.push({x,y,hp:rand(1,3)>2?2:1,face:x<player.x?1:-1,attack:rand(.3,1),cool:rand(.2,.8),flash:0,anim:rand(0,5),speed:rand(52,76),type:Math.floor(rand(0,3)),seed:rand(0,100)}); }
  function burst(x,y,color,n=8){for(let i=0;i<n;i++){let a=rand(0,Math.PI*2),v=rand(45,180);particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:rand(.25,.55),max:.55,color,size:rand(2,5)})}}
  function punch(){if(state.mode!=='playing'||player.attack>0||player.dash>0)return;player.attack=.25;sound(220,.07,'square',.025);let hit=false;for(const e of enemies){const dx=e.x-player.x,dy=e.y-player.y,front=dx*player.face;if(front>-14&&front<88&&Math.abs(dy)<48){e.hp--;e.flash=.13;e.x+=player.face*23;e.y+=dy*.12;state.score+=100;hit=true;burst(e.x,e.y-35,'#ffd966',6);sound(145,.08,'sawtooth',.045);if(e.hp<=0){state.defeats++;state.score+=250;burst(e.x,e.y-28,'#f26c3a',13);if(Math.random()<.66)snacks.push({x:e.x,y:e.y,age:0});showToast(['NICE ONE!','THAT'+'\'S THE SPIRIT!','BULLY DOWN!'][Math.floor(rand(0,3))]);} }}enemies=enemies.filter(e=>e.hp>0);if(!hit) sound(115,.06,'triangle',.02);updateHud(); }
  function dash(){if(state.mode!=='playing'||player.dashLock>0)return;let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0);let dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);if(!dx&&!dy)dx=player.face;let m=Math.hypot(dx,dy);player.vx=dx/m*520;player.vy=dy/m*520;player.dash=.16;player.dashLock=.8;player.invuln=.24;burst(player.x,player.y-15,'#fff1c4',5);sound(320,.1,'triangle');}

