function drawCharacter(ch,isPlayer=false){
  const moving=Math.hypot(ch.vx||0,ch.vy||0)>20||(!isPlayer&&ch.mode==='chase');const stride=moving?Math.sin(state.anim*13+(ch.anim||0))*3:Math.sin(state.anim*3+(ch.anim||0))*1.2;
  ctx.save();ctx.translate(ch.x,ch.y);if(ch.flash>0&&Math.floor(state.anim*45)%2===0)ctx.globalAlpha=.48;
  // soft foot shadow
  ctx.fillStyle='#59423955';ctx.beginPath();ctx.ellipse(0,-1,22,7,0,0,Math.PI*2);ctx.fill();
  // legs + shoes
  ctx.fillStyle=isPlayer?'#386e66':ch.type===1?'#bd6247':ch.type===2?'#554e79':'#496c83';
  ctx.fillRect(-10,-23+stride,9,21);ctx.fillRect(2,-23-stride,9,21);
  ctx.fillStyle='#423b37';ctx.fillRect(-13,-6+stride,14,6);ctx.fillRect(0,-6-stride,14,6);
  // torso, iconic green shorts and striped top
  if(isPlayer){ctx.fillStyle='#506a49';ctx.fillRect(-13,-54,26,34);ctx.fillStyle='#e7e2c6';ctx.fillRect(-12,-52,24,7);ctx.fillStyle='#607c53';ctx.fillRect(-12,-45,24,8);ctx.fillStyle='#f0e7ca';ctx.fillRect(-12,-37,24,7);ctx.fillStyle='#607c53';ctx.fillRect(-12,-30,24,9);ctx.fillStyle='#4b6848';ctx.fillRect(-13,-27,26,7)}else{ctx.fillStyle=ch.type===1?'#bc593d':ch.type===2?'#655883':'#dbb64d';ctx.fillRect(-14,-53,28,34);ctx.fillStyle='#f3dfb0';ctx.fillRect(-14,-51,28,7);ctx.fillStyle=ch.type===1?'#bc593d':ch.type===2?'#655883':'#dbb64d';ctx.fillRect(-14,-44,28,7);ctx.fillStyle='#f3dfb0';ctx.fillRect(-14,-37,28,7);ctx.fillStyle=ch.type===1?'#bc593d':ch.type===2?'#655883':'#dbb64d';ctx.fillRect(-14,-30,28,10);ctx.fillStyle='#3f5047';ctx.fillRect(-15,-25,30,7)}
  // arms and fist swing
  const swinging= isPlayer?ch.attack>0:ch.attack>0;const side=ch.face||1;
  ctx.strokeStyle=isPlayer?'#cf916a':'#d99a70';ctx.lineWidth=7;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-11,-48);ctx.lineTo(-17,-34);ctx.moveTo(11,-48);ctx.lineTo(swinging?24*side:17,swinging?-42:-34);ctx.stroke();
  if(swinging){ctx.fillStyle='#fff0c0';ctx.beginPath();ctx.arc(side*30,-42,5+Math.sin(state.anim*35)*2,0,Math.PI*2);ctx.fill()}
  // neck and head
  ctx.fillStyle=isPlayer?'#d89b70':'#dba078';ctx.fillRect(-5,-61,10,9);ctx.fillStyle=isPlayer?'#d89b70':'#dba078';ctx.beginPath();ctx.ellipse(0,-72,14,15,0,0,Math.PI*2);ctx.fill();
  // ears
  ctx.fillStyle='#c98562';ctx.beginPath();ctx.arc(-14,-72,3,0,Math.PI*2);ctx.arc(14,-72,3,0,Math.PI*2);ctx.fill();
  if(isPlayer){ // brown aviator cap with ear flaps
    ctx.fillStyle='#79563c';ctx.beginPath();ctx.ellipse(0,-81,17,8,0,Math.PI,Math.PI*2);ctx.fill();ctx.fillRect(-16,-82,32,5);ctx.fillStyle='#68452f';ctx.fillRect(-17,-79,6,9);ctx.fillRect(11,-79,6,9);ctx.fillStyle='#a57b52';ctx.fillRect(-11,-86,22,3);
  }else{ctx.fillStyle=ch.type===1?'#394d61':ch.type===2?'#b77242':'#4e6148';ctx.beginPath();ctx.ellipse(0,-82,16,8,0,Math.PI,Math.PI*2);ctx.fill();ctx.fillRect(-17,-82,34,4);ctx.fillStyle='#29383a';ctx.fillRect(-10,-74,4,3);}
