}
function drawSnack(s){ctx.save();ctx.translate(s.x,s.y-18+Math.sin(s.age*6)*4);ctx.fillStyle='#46362e55';ctx.beginPath();ctx.ellipse(0,22,14,4,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f3d171';ctx.beginPath();ctx.arc(0,0,12,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ba7045';ctx.beginPath();ctx.arc(0,0,7,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff0b7';ctx.beginPath();ctx.arc(-3,-3,3,0,Math.PI*2);ctx.fill();ctx.restore()}
function draw(){ctx.save();if(state.shake>0)ctx.translate(rand(-state.shake,state.shake),rand(-state.shake,state.shake));drawBackground();snacks.forEach(drawSnack);const actors=[...enemies.map(e=>({o:e,p:false})),{o:player,p:true}].sort((a,b)=>a.o.y-b.o.y);actors.forEach(({o,p})=>drawCharacter(o,p));particles.forEach(p=>{ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.fillRect(p.x-p.size/2,p.y-p.size/2,p.size,p.size)});ctx.globalAlpha=1;ctx.restore();}

